import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import ts from 'typescript';
// React Native rejects literal children in View even though React Native Web accepts them.
function invalidText(source, path) {
  const file = ts.createSourceFile(path, source, ts.ScriptTarget.Latest, true, ts.ScriptKind.TSX);
  const failures = [];
  const textNames = new Set(['Text', 'NativeText', 'ThemedText']);
  for (const statement of file.statements) {
    if (ts.isImportDeclaration(statement)) {
      const bindings = statement.importClause?.namedBindings;
      if (bindings && ts.isNamedImports(bindings))
        for (const specifier of bindings.elements) {
          if ((specifier.propertyName?.text ?? specifier.name.text) === 'Text')
            textNames.add(specifier.name.text);
        }
    }
  }
  function walk(node) {
    const literal = ts.isJsxText(node)
      ? node.text.trim()
      : ts.isJsxExpression(node) && node.expression && ts.isStringLiteral(node.expression)
        ? node.expression.text
        : '';
    if (literal) {
      let parent = node.parent;
      while (parent && ts.isJsxFragment(parent)) parent = parent.parent;
      if (parent && ts.isJsxElement(parent)) {
        const tag = parent.openingElement.tagName.getText(file);
        if (!textNames.has(tag) && !/\.Text$/.test(tag))
          failures.push(`${path}:${file.getLineAndCharacterOfPosition(node.pos).line + 1}`);
      }
    }
    ts.forEachChild(node, walk);
  }
  walk(file);
  return failures;
}
test('native sources do not place literal text or explicit spaces outside Text', () => {
  assert.equal(invalidText("<View>{' '}</View>", 'fixture.tsx').length, 1);
  assert.equal(invalidText('<View><Text>Hello</Text></View>', 'fixture.tsx').length, 0);
  const root = 'apps/mobile/src/';
  const failures = readdirSync(root, { recursive: true })
    .filter((p) => p.endsWith('.tsx') && !p.includes('.test.'))
    .flatMap((p) => invalidText(readFileSync(root + p, 'utf8'), root + p));
  assert.deepEqual(failures, []);
});

import { useEffect, useMemo, useState } from 'react';
import {
  createInventoryClient,
  createPricingClient,
  productQuantityForm,
} from '@inventory/api-client';
import { hasPermission, type Business, type Location, type Product } from '@inventory/contracts';
import { authClient } from '../auth/client';
import { operationKey } from '../platform/operation-key';
import { View } from 'react-native';
import { Text } from '../ui/Themed';
import { CommandForm } from '../components/CommandForm';
import { Action } from '../ui/Controls';
export function ProductQuantity({
  business,
  locations,
  product,
  opening,
  run,
  busy,
}: {
  business: Business;
  locations: Location[];
  product: Product;
  opening: boolean;
  busy: boolean;
  run: (work: () => Promise<unknown>) => void;
}) {
  const client = useMemo(
    () => createInventoryClient(authClient.organizationRequest, operationKey, business.id),
    [business.id],
  );
  const pricing = useMemo(
    () => createPricingClient(authClient.organizationRequest, business.id, product.id),
    [business.id, product.id],
  );
  const [data, setData] = useState<Awaited<ReturnType<typeof pricing.load>> | null>(null);
  const [recorded, setRecorded] = useState(false);
  const [error, setError] = useState(''),
    [retry, setRetry] = useState(0),
    [saved, setSaved] = useState(false);
  useEffect(() => {
    let active = true;
    void pricing
      .load()
      .then((value) => {
        if (active) {
          setData(value);
          setError('');
        }
      })
      .catch(() => {
        if (active) setError('Unable to load stock units. Retry when connected.');
      });
    return () => {
      active = false;
    };
  }, [pricing, retry]);
  if (!hasPermission(business, 'stock.write'))
    return <Text>You do not have permission to change stock quantities.</Text>;
  if (!product.trackInventory || product.type === 'service')
    return <Text>This product does not track stock quantities.</Text>;
  if (product.state !== 'active') return <Text>Activate this product before adding stock.</Text>;
  if (!locations.some((l) => l.kind === 'warehouses' && l.state === 'active'))
    return (
      <Text>
        Add or select an active warehouse before recording quantity. Product details remain saved.
      </Text>
    );
  if (error)
    return (
      <>
        <Text>{error}</Text>
        <Action
          label="Retry"
          onPress={() => {
            setError('');
            setRetry((n) => n + 1);
          }}
        />
      </>
    );
  if (!data) return <Text>Loading stock units…</Text>;
  if (!data.variants.some((v) => v.state === 'active'))
    return <Text>Add an active variant in Price & units before recording quantity.</Text>;
  return (
    <View accessibilityLabel="Product quantity">
      <Text>
        Enter the number of units to{' '}
        {opening && !recorded ? 'add as opening stock' : 'add or remove'}, not a replacement total.
        This records a stock movement at the warehouse root. Use Stock & movements for specific bins
        or counts.
      </Text>
      {saved ? (
        <>
          <Text>Quantity saved. The stock movement is recorded.</Text>
          <Action
            label="Record another quantity change"
            disabled={busy}
            onPress={() => setSaved(false)}
          />
        </>
      ) : (
        <View pointerEvents={busy ? 'none' : 'auto'} accessibilityState={{ disabled: busy }}>
          {' '}
          <CommandForm
            inline
            definition={productQuantityForm(client, data, locations, opening && !recorded)}
            run={(work) =>
              run(async () => {
                await work();
                setSaved(true);
                setRecorded(true);
              })
            }
          />
        </View>
      )}
    </View>
  );
}

