  .quantity-control button {
    min-width: var(--target-size);
  }
  .ui-checkbox {
    min-width: var(--target-size);
    min-height: var(--target-size);
  }
}

/* Density cannot resize controls via inherited gap/padding utilities. */
[data-slot='input'],
[data-slot='textarea'],
.select-trigger,
.search-control input,
[data-slot='button']:not([data-size^='icon']),
.view-tabs button,
.segmented-options span {
